func (p *pagePathBuilder) toPermalinkSliceFunc(cut string) func(s []string) []string {
	if p.permalinkAttributes == nil && strings.TrimSpace(cut) == "" {
		return allSliceFunc
	}
	cut = strings.ToLower(strings.TrimSpace(cut))
	if cut == "" {
		return allSliceFunc
	}
	if len(cut) < 3 || (cut[0] != '[' || cut[len(cut)-1] != ']') {
		return nilSliceFunc
	}
	toNFunc := func(s string, low bool) func(ss []string) int {
		if s == "" {
			if low {
				return func(ss []string) int {
					return 0
				}
			}
			return func(ss []string) int {
				return len(ss)
			}
		}
		if s == "last" {
			return func(ss []string) int {
				return len(ss) - 1
			}
		}
		n, _ := strconv.Atoi(s)
		if n < 0 {
			n = 0
		}
		return func(ss []string) int {
			if n >= len(ss) {
				if low {
					return -1
				}
				return len(ss)
			}
			return n
		}
	}
	opsStr := cut[1 : len(cut)-1]
	opts := strings.Split(opsStr, ":")
	if !strings.Contains(opsStr, ":") {
		toN := toNFunc(opts[0], true)
		return func(s []string) []string {
			if len(s) == 0 {
				return nil
			}
			n := toN(s)
			if n < 0 {
				return []string{}
			}
			v := s[n]
			if v == "" {
				return nil
			}
			return []string{v}
		}
	}
	toN1, toN2 := toNFunc(opts[0], true), toNFunc(opts[1], false)
	return func(s []string) []string {
		if len(s) == 0 {
			return nil
		}
		n1, n2 := toN1(s), toN2(s)
		if n1 < 0 || n2 < 0 {
			return []string{}
		}
		return s[n1:n2]
	}
}

