func PathEscape(pth string) string {
	// url.Parse treats # and ? as the start of the fragment and query,
	// respectively, but this is a path where they should be escaped.
	if strings.ContainsAny(pth, "#?") {
		pth = strings.NewReplacer("#", "%23", "?", "%3F").Replace(pth)
	}
	u, err := url.Parse(pth)
	if err != nil {
		panic(err)
	}
	return u.EscapedPath()
